from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,pandas as pd,numpy as np,patsy
R=Path(__file__).resolve().parent;S=R/'public_source_qualification/StJude_pharmacotype_public_link_20261010';M=R/'independent_StJude_pharmacotype_maturation_MRD';O=R/'independent_StJude_ZEB1_patient_drug_response';O.mkdir(exist_ok=True)
sources={'native_clinical_and_LC50':S/'OFFICIAL_ORIGINAL_CLINICAL_ATTACHMENT_READBACK.xlsx','primary_fulltext':S/'CORRECT_LEE_PHARMACOTYPE_NATIVE_FULLTEXT.xml','original_116_covariates':M/'ALL116_FIXED_PROXY_AND_CLINICAL_COVARIATES.tsv','full_maturity_gate':M/'INPUT_QUALIFICATION.json','four_gene_FPKM':M/'EXACT_FOUR_GENE_FPKM_SOURCE_READBACK.tsv','original_RNA_matched_clinical':M/'EXACT_RNA_MATCHED_ORIGINAL_CLINICAL_FIELDS.tsv','prior_continuous_MRD':M/'SEPARATE_MRD_THREE_MARKER_RESULTS.json','prior_binary_MRD':M/'fixed_MRD_positive_sensitivity/FIXED_BINARY_MRD_RESULTS.json'}
def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()
assert not (O/'RESULTS.json').exists(),'Do not refreeze after viewing drug associations'
native=pd.read_excel(sources['native_clinical_and_LC50'],sheet_name='Supp Table 1.',header=2)
drugfields=[c for c in native.columns if c.endswith('_normalized')];assert len(drugfields)==18
contract={'created_utc':datetime.now(timezone.utc).isoformat(),'status':'FROZEN_BEFORE_NEW_PATIENT_GENE_DRUG_COEFFICIENTS','scientific_question':'Within the already qualified independent StJude TALL116 diagnostic cohort, does continuous ZEB1 associate with measured/reported single-drug LC50 response after baseline clinical/ETP adjustment and the pre-existing fixed three-marker immaturity proxy? Is any signal drug-specific and robust to ties/rank transformation?','prior_exposure':'Previously inspected MRD and GDSC results motivated this new explicitly exploratory question. Drug availability/endpoint distributions and native methods have been inspected; no new ZEB1-drug association coefficients have been viewed. Not preregistration.','unit':'Patients, one diagnostic provider summary per drug. RNA116 is reused from prior MRD, not a second independent patient cohort. Dose wells, technical assays, cells and drugs are not independent patients.','source':'Lee et al., Nature Medicine2023 PMID36604538 DOI10.1038/s41591-022-02112-7 official clinical/LC50 XLSX plus author public RNA FPKM and exact patient bridge. Original main AALL0434 and this cohort are not combined.','drugs':drugfields,'all_drugs_retained':'All18 represented in a 72-slot target ledger, including unestimated drugs; no selected significant-drug subset, grouping/cutoff or imputation.','exposure':'Exact existing ZEB1 log2(FPKM+1) per1 unit across original116; no outcome-driven probe, threshold or rescaling.','proxy':'Exact existing dev and dev_squared from CD1A/CD34/LYL1 log2(FPKM+1) standardized once on all116 with population SD; excludes ZEB1. Full fixed200 mature programme input gate remains failed/unestimated. This separate proxy never substitutes for full maturation.','base':'ZEB1 + age_years + log10_WBC_plus1 + male + categorical Protocol + categorical native Molecular subtype (T-ALL/ETP). No post-baseline MRD or survival adjustment.','proxy_adjusted':'base plus existing dev and dev_squared. All factors use observed complete-case levels; absent protocol/subtype levels are recorded as unrepresented, not inferred zero effects.','primary_endpoint':'Exact author-released normalized LC50 in [0,1], larger means higher reported resistance. Original methods log-transform raw LC50 and normalize by tested min/max concentration; no new normalization or inversion. The conditional mean estimand concerns this bounded reported assay summary, not latent uncensored concentration or clinical treatment benefit.','sensitivity_endpoint':'Fractional midrank=(average rank-0.5)/n among the original116 RNA-matched patients with measured value for that drug before covariate filtering. Ties retained. Rank is an ordinal reported-summary endpoint, not censoring deconvolution.','missingness':'No imputation of drug/expression/covariates. Per-drug same complete-case set for both models and both transforms; preserve all116 missingness for every drug. No across-drug common-case intersection or eligibility based on MRD/OS.','input_gate':'Before coefficients, require n>=30, >=10 distinct reported normalized values, full rank for both fixed designs and residual df>=20 in the larger model. Failure remains UNESTIMATED with no relaxed cutoff or fallback model.','method':'Maintained statsmodels OLS, HC3 covariance with residual-df t Wald interval/P, full coefficients and designs. All-patient analytical leave-one-out slope and leverage/rank/condition diagnostics are reported and do not select exclusions.','multiplicity':'72 planned exploratory slots (18 drugs x2 models x2 endpoint representations). Compute BH using m=72 for estimated P values, leaving unestimated P/q absent rather than fabricating P=1. Also report combined m=80 sensitivity with the8 prior continuous/binary MRD target tests on this same116 source. Preserve prior published MRD families unchanged. Neither is project-wide confirmatory error control.','boundaries':['Drug-specific endpoint coefficients are separate and are not a formal between-drug interaction or evidence of ZEB1 causality.','ETP label and three markers are incomplete developmental proxies; genomic subtype/response programme confounding may remain.','Observed drug testing may depend on protocol/available cells; complete-case estimates may not generalize to untested patients.','Upper/lower endpoint ties and tested-dose bounds are retained; cannot extrapolate latent LC50 beyond assay range.','No independent OS replication, direct ZEB1 perturbation, therapeutic recommendation, pharmacotype-cluster refit, manuscript/figure sync or accepted Cox/SU/MC/D rerun.'],'sources':{k:{'path':str(p),'sha256':h(p)} for k,p in sources.items()}}
cp=O/'PREVALUE_CONTRACT.json';cp.write_text(json.dumps(contract,indent=2,ensure_ascii=False),encoding='utf-8')
cov=pd.read_csv(sources['original_116_covariates'],sep='\t',index_col=0);cov.index=cov.index.astype(str);assert len(cov)==116 and cov.index.is_unique
native['Patient ID']=native['Patient ID'].astype(str);assert native['Patient ID'].is_unique
t=cov.reset_index().merge(native[['Patient ID','Immunophenotype','Molecular subtype']+drugfields],on='Patient ID',how='left',validate='one_to_one',sort=False)
assert len(t)==116 and t.Immunophenotype.eq('T').all() and set(t['Molecular subtype'])=={'T-ALL','ETP'}
t=t.rename(columns={'Patient ID':'patient_id','Molecular subtype':'native_subtype'});assert np.isfinite(t[['ZEB1','dev','dev_squared','age_years','log10_WBC_plus1','male']]).all().all()
forms={'base':'ZEB1 + age_years + log10_WBC_plus1 + male + C(Protocol) + C(native_subtype)','proxy_adjusted':'ZEB1 + age_years + log10_WBC_plus1 + male + C(Protocol) + C(native_subtype) + dev + dev_squared'}
gate=[];ledgers=[];prior=[]
for row in json.loads(sources['prior_continuous_MRD'].read_text(encoding='utf-8'))['results']:
    prior.append({'family':'prior_continuous_MRD','outcome':row['outcome'],'model':row['model'],'P':row['HC3_t_p']})
b=json.loads(sources['prior_binary_MRD'].read_text(encoding='utf-8'))
for row in b['target_associations']:
    candidates=[(k,v) for k,v in row.items() if k.lower() in ['p','p_value','wald_p','zeb1_p','pvalue']]
    assert len(candidates)==1,(row,candidates)
    prior.append({'family':'prior_binary_MRD','outcome':row.get('outcome'),'model':row.get('model'),'P':candidates[0][1]})
assert len(prior)==8 and all(np.isfinite(x['P']) and 0<=x['P']<=1 for x in prior)
(O/'ORIGINAL_EIGHT_MRD_TARGET_P_VALUES_READBACK.json').write_text(json.dumps(prior,indent=2),encoding='utf-8')
needed=['ZEB1','dev','dev_squared','age_years','log10_WBC_plus1','male','Protocol','native_subtype']
for field in drugfields:
    drug=field.removesuffix('_normalized');v=pd.to_numeric(t[field],errors='coerce')
    rawvalid=v.notna();assert v[rawvalid].between(0,1).all()
    t[field+'_fractional_midrank']=(v.rank(method='average')-.5)/int(rawvalid.sum())
    missing=t[needed].isna();keep=rawvalid&~missing.any(axis=1);x=t.loc[keep,['patient_id']+needed+[field,field+'_fractional_midrank']].copy()
    reasons=[]
    if len(x)<30:reasons.append('n_patients_below30')
    if x[field].nunique()<10:reasons.append('distinct_reported_values_below10')
    designq={}
    for model,f in forms.items():
        X=patsy.dmatrix(f,x,return_type='dataframe') if len(x) else pd.DataFrame()
        rank=int(np.linalg.matrix_rank(X)) if len(X) else 0;k=X.shape[1];df=len(x)-k
        designq[model]={'n_coefficients':k,'rank':rank,'residual_df':df,'terms':list(X)}
        if rank!=k:reasons.append(model+'_rank_deficient')
        if df<20:reasons.append(model+'_residual_df_below20')
        X.to_csv(O/(drug+'_'+model+'_FROZEN_DESIGN.tsv'),sep='\t',index=False)
    item={'drug':drug,'native_field':field,'n_original116_measured':int(rawvalid.sum()),'n_complete_patients':len(x),'n_missing_drug':int((~rawvalid).sum()),'n_missing_required_covariates':int(missing.any(axis=1).sum()),'n_distinct_complete_values':int(x[field].nunique()),'base_and_proxy_samecases':True,'represented_protocols':sorted(x.Protocol.unique().tolist()),'unrepresented_protocols':sorted(set(t.Protocol)-set(x.Protocol)),'represented_native_subtypes':sorted(x.native_subtype.unique().tolist()),'unrepresented_native_subtypes':sorted(set(t.native_subtype)-set(x.native_subtype)),'designs':designq,'gate_pass':not reasons,'failure_reasons':reasons}
    gate.append(item);x.to_csv(O/(drug+'_FROZEN_COMPLETECASE_INPUT.tsv'),sep='\t',index=False)
    for i,pid in enumerate(t.patient_id):ledgers.append({'drug':drug,'patient_id':pid,'drug_measured':bool(rawvalid.iloc[i]),'all_baseline_covariates_present':bool(not missing.iloc[i].any()),'included_in_samecase_input':bool(keep.iloc[i]),'model_gate_pass':not reasons})
t.to_csv(O/'ALL116_FIXED_BASELINE_AND_NATIVE_DRUG_DATA.tsv',sep='\t',index=False);pd.DataFrame(ledgers).to_csv(O/'ALL_18_DRUGS_116_PATIENT_AVAILABILITY_LEDGER.tsv',sep='\t',index=False)
qual={'created_utc':datetime.now(timezone.utc).isoformat(),'n_independent_patients_reference':116,'n_original18_drugs':18,'planned_target_tests':72,'estimated_drug_gate_n':sum(x['gate_pass'] for x in gate),'unestimated_drug_gate_n':sum(not x['gate_pass'] for x in gate),'drug_gates':gate,'prior_MRD_tests':8,'full_maturity_gate_retained_unestimated':True,'new_drug_coefficients_inspected':False,'contract_sha256':h(cp),'sources':contract['sources']}
(O/'INPUT_QUALIFICATION.json').write_text(json.dumps(qual,indent=2,ensure_ascii=False),encoding='utf-8')
print('NEW_DRUG_INPUT_GATE',json.dumps({'estimated_drugs':[{'drug':x['drug'],'n':x['n_complete_patients'],'k':x['designs']['proxy_adjusted']['n_coefficients']} for x in gate if x['gate_pass']],'unestimated_drugs':[{'drug':x['drug'],'n':x['n_complete_patients'],'reasons':x['failure_reasons']} for x in gate if not x['gate_pass']],'planned_family':72,'prior_MRD_sensitivity':8}))
